_AUTO_GENERATED_FILE_PAGINATION_SPEC = PaginationSpec(
    forward_order=AutoGeneratedFileSearchableFields.own.created_at.order.apply(ascending=False),
    cursor_column=AutoGeneratedFileRow.id,
)


_AUTO_GENERATED_FILE_REVISION_PAGINATION_SPEC = PaginationSpec(
    forward_order=AutoGeneratedFileRevisionSearchableFields.own.revision_number.order.apply(
        ascending=False
    ),
    cursor_column=AutoGeneratedFileRevisionRow.id,
)


class AutoGeneratedFileAdapter(BaseAdapter):
    _auto_generated_file: AutoGeneratedFileProcessors

    def __init__(self, auto_generated_file: AutoGeneratedFileProcessors) -> None:
        self._auto_generated_file = auto_generated_file

    async def _search_default_auto_generated_files(
        self, owner: EntityIdentifier, path: str | None = None
    ) -> list[AutoGeneratedFileData]:
        fields = AutoGeneratedFileSearchableFields.own
        conditions = [fields.is_default.filter.equals(True)]
        if path is not None:
            conditions.append(
                fields.path.filter.equals(
                    StringMatchSpec(value=path, case_insensitive=False, negated=False)
                )
            )
        result = await self._auto_generated_file.search.run(
            SearchAutoGeneratedFilesAction(
                targets=[AutoGeneratedFileTarget.of_owner(owner)],
                searcher=AutoGeneratedFileSearcher(
                    pagination=NoPagination(),
                    conditions=conditions,
                    orders=[fields.created_at.order.apply(True), fields.id.order.apply(True)],
                ),
            )
        )
        return result.items

    async def _default_auto_generated_file_entries(
        self, owner: EntityIdentifier, path: str | None = None
    ) -> list[DotfileEntry]:
        """The owner's default files with their current content, read off the latest revisions."""
        auto_generated_files = await self._search_default_auto_generated_files(owner, path)
        if not auto_generated_files:
            return []
        revisions = await self._auto_generated_file.get_current_revisions.run(
            GetCurrentAutoGeneratedFileRevisionsAction(
                auto_generated_file_ids=[file.id for file in auto_generated_files]
            )
        )
        return [
            DotfileEntry(
                path=file.path,
                perm=revisions.designated[file.id].perm,
                data=revisions.designated[file.id].data,
            )
            for file in auto_generated_files
        ]

    async def create_default_auto_generated_file(
        self, input: CreateDefaultAutoGeneratedFileInput
    ) -> GetDotfileResponse:
        """Add a file and make it the default of its path, in two separate writes."""
        created = await self._auto_generated_file.create.run(
            CreateAutoGeneratedFileAction(
                creator=AutoGeneratedFileCreator(
                    owner=input.owner,
                    entry=DotfileEntry(path=input.path, perm=input.perm, data=input.data),
                ),
                creator_id=input.creator_id,
            )
        )
        result = await self._auto_generated_file.switch_default.run(
            SwitchDefaultAutoGeneratedFileAction(
                owner=input.owner, auto_generated_file_id=created.data.id
            )
        )
        return GetDotfileResponse(path=result.data.path, perm=input.perm, data=input.data)

    async def get_default_auto_generated_file_by_path(
        self, owner: EntityIdentifier, path: str
    ) -> GetDotfileResponse:
        entries = await self._default_auto_generated_file_entries(owner, path)
        if not entries:
            raise DotfileNotFound
        entry = entries[0]
        return GetDotfileResponse(path=entry.path, perm=entry.perm, data=entry.data)

    async def list_default_auto_generated_files(
        self, owner: EntityIdentifier
    ) -> list[DotfileListItem]:
        entries = await self._default_auto_generated_file_entries(owner)
        return [DotfileListItem(path=e.path, permission=e.perm, data=e.data) for e in entries]

    async def update_default_auto_generated_file(
        self, input: UpdateDefaultAutoGeneratedFileInput
    ) -> GetDotfileResponse:
        auto_generated_files = await self._search_default_auto_generated_files(
            input.owner, input.path
        )
        if not auto_generated_files:
            raise DotfileNotFound
        result = await self._auto_generated_file.update.run(
            UpdateAutoGeneratedFileAction(
                auto_generated_file_id=auto_generated_files[0].id,
                revision=AutoGeneratedFileRevisionSpec(
                    data=input.data, perm=input.perm, creator_id=input.creator_id
                ),
            )
        )
        return GetDotfileResponse(path=result.data.path, perm=input.perm, data=input.data)

    async def purge_default_auto_generated_file(
        self, input: PurgeDefaultAutoGeneratedFileInput
    ) -> DeleteDotfileResponse:
        auto_generated_files = await self._search_default_auto_generated_files(
            input.owner, input.path
        )
        if not auto_generated_files:
            raise DotfileNotFound
        await self._auto_generated_file.purge_default.run(
            PurgeDefaultAutoGeneratedFileAction(auto_generated_file_id=auto_generated_files[0].id)
        )
        return DeleteDotfileResponse(success=True)

    async def create(self, input: CreateAutoGeneratedFileInput) -> CreateAutoGeneratedFilePayload:
        """Add a file that is not the default of its path, written by the acting user."""
        me = current_user()
        if me is None:
            raise UnreachableError("User context is not available")
        result = await self._auto_generated_file.create.run(
            CreateAutoGeneratedFileAction(
                creator=AutoGeneratedFileCreator(
                    owner=self._scope_entity(input.scope),
                    entry=DotfileEntry(path=input.path, perm=input.permission, data=input.data),
                ),
                creator_id=UserID(me.user_id),
            )
        )
        return CreateAutoGeneratedFilePayload(auto_generated_file=self._to_node(result.data))

    async def get(self, auto_generated_file_id: AutoGeneratedFileID) -> GetAutoGeneratedFilePayload:
        result = await self._auto_generated_file.get.run(
            GetAutoGeneratedFileAction(auto_generated_file_id=auto_generated_file_id)
        )
        return GetAutoGeneratedFilePayload(auto_generated_file=self._to_node(result.data))

    async def bulk_get_ids(
        self, ids: Sequence[AutoGeneratedFileID]
    ) -> list[AutoGeneratedFileNode | Exception | None]:
        """Batch load files by id for DataLoader use, one answer per id."""
        if not ids:
            return []
        result = await self._auto_generated_file.bulk_get.run(
            BulkGetAutoGeneratedFilesAction(ids=list(ids))
        )
        return [
            self._to_node(item.value)
            if item.value is not None
            else self.batch_load_failure(item.error)
            for item in result.items
        ]

    async def add_revision(
        self, input: AddAutoGeneratedFileRevisionInput
    ) -> AddAutoGeneratedFileRevisionPayload:
        """Add the next revision of a file's content and permission, written by the acting
        user."""
        me = current_user()
        if me is None:
            raise UnreachableError("User context is not available")
        result = await self._auto_generated_file.add_revision.run(
            AddAutoGeneratedFileRevisionAction(
                auto_generated_file_id=input.auto_generated_file_id,
                revision=AutoGeneratedFileRevisionSpec(
                    data=input.data, perm=input.permission, creator_id=UserID(me.user_id)
                ),
            )
        )
        return AddAutoGeneratedFileRevisionPayload(revision=self._to_revision_node(result.data))

    async def bulk_get_revision_ids(
        self, ids: Sequence[AutoGeneratedFileRevisionID]
    ) -> list[AutoGeneratedFileRevisionNode | Exception | None]:
        """Batch load revisions by id for DataLoader use, one answer per id."""
        if not ids:
            return []
        return await self.batch_load_fields(
            self._auto_generated_file.bulk_get_revisions,
            BulkGetAutoGeneratedFileRevisionsAction(ids=list(ids)),
            ids,
            self._to_revision_node,
        )

    async def search_revisions(
        self, input: SearchAutoGeneratedFileRevisionsInput
    ) -> SearchAutoGeneratedFileRevisionsPayload:
        """Search the revisions of one file."""
        searcher = self._build_searcher(
            AutoGeneratedFileRevisionSearcher,
            conditions=self._convert_revision_filter(input.filter) if input.filter else [],
            orders=[self._convert_revision_order(o) for o in input.order] if input.order else [],
            pagination_spec=_AUTO_GENERATED_FILE_REVISION_PAGINATION_SPEC,
            first=input.first,
            after=input.after,
            last=input.last,
            before=input.before,
            limit=input.limit,
            offset=input.offset,
        )
        result = await self._auto_generated_file.search_revisions.run(
            SearchAutoGeneratedFileRevisionsAction(
                auto_generated_file_id=input.auto_generated_file_id, searcher=searcher
            )
        )
        return SearchAutoGeneratedFileRevisionsPayload(
            items=[self._to_revision_node(item) for item in result.items],
            total_count=result.total_count,
            has_next_page=result.has_next_page,
            has_previous_page=result.has_previous_page,
        )

    async def purge(self, input: PurgeAutoGeneratedFileInput) -> PurgeAutoGeneratedFilePayload:
        """Remove a file that is not the default of its path; the default is refused."""
        await self._auto_generated_file.purge.run(
            PurgeAutoGeneratedFileAction(auto_generated_file_id=input.id)
        )
        return PurgeAutoGeneratedFilePayload(entity_id=input.id)

    async def scoped_search(
        self, input: ScopedSearchAutoGeneratedFilesInput
    ) -> SearchAutoGeneratedFilesPayload:
        """Search the files of the named domains, projects and users, combined with OR."""
        targets: list[AutoGeneratedFileTarget] = [
            DomainAutoGeneratedFileTarget(DomainID(entry.value))
            for entry in input.scope.domain or []
        ]
        targets.extend(
            ProjectAutoGeneratedFileTarget(ProjectID(entry.value))
            for entry in input.scope.project or []
        )
        targets.extend(
            UserAutoGeneratedFileTarget(UserID(entry.value)) for entry in input.scope.user or []
        )
        searcher = self._build_searcher(
            AutoGeneratedFileSearcher,
            conditions=self._convert_filter(input.filter) if input.filter else [],
            orders=[self._convert_order(o) for o in input.order] if input.order else [],
            pagination_spec=_AUTO_GENERATED_FILE_PAGINATION_SPEC,
            first=input.first,
            after=input.after,
            last=input.last,
            before=input.before,
            limit=input.limit,
            offset=input.offset,
        )
        result = await self._auto_generated_file.search.run(
            SearchAutoGeneratedFilesAction(targets=targets, searcher=searcher)
        )
        return SearchAutoGeneratedFilesPayload(
            items=[self._to_node(item) for item in result.items],
            total_count=result.total_count,
            has_next_page=result.has_next_page,
            has_previous_page=result.has_previous_page,
        )

    async def switch_default(
        self, input: SwitchDefaultAutoGeneratedFileInput
    ) -> SwitchDefaultAutoGeneratedFilePayload:
        """Make a file the default of its path; the previous default stops being one."""
        result = await self._auto_generated_file.switch_default.run(
            SwitchDefaultAutoGeneratedFileAction(
                owner=self._scope_entity(input.scope), auto_generated_file_id=input.id
            )
        )
        return SwitchDefaultAutoGeneratedFilePayload(auto_generated_file=self._to_node(result.data))

    def _convert_filter(self, filter: AutoGeneratedFileFilter) -> list[QueryCondition]:
        fields = AutoGeneratedFileSearchableFields.own
        conditions = [
            *self.apply_uuid_filter(filter.entity_id, fields.id.filter),
            *self._scope_type_conditions(filter.scope_type),
            *self.apply_uuid_filter(filter.scope_id, fields.entity_id.filter),
            *self.apply_string_filter(filter.path, fields.path.filter),
            *self.apply_datetime_filter(filter.created_at, fields.created_at.filter),
            *self.apply_datetime_filter(filter.updated_at, fields.updated_at.filter),
        ]
        if filter.is_default is not None:
            conditions.append(fields.is_default.filter.equals(filter.is_default))
        if filter.AND:
            for sub_filter in filter.AND:
                conditions.extend(self._convert_filter(sub_filter))
        if filter.OR:
            or_sub_conditions: list[QueryCondition] = []
            for sub_filter in filter.OR:
                sub_conditions = self._convert_filter(sub_filter)
                if sub_conditions:
                    or_sub_conditions.append(combine_conditions_and(sub_conditions))
            if or_sub_conditions:
                conditions.append(combine_conditions_or(or_sub_conditions))
        if filter.NOT:
            for sub_filter in filter.NOT:
                sub_conditions = self._convert_filter(sub_filter)
                if sub_conditions:
                    conditions.append(negate_conditions(sub_conditions))
        return conditions

    def _convert_revision_filter(
        self, filter: AutoGeneratedFileRevisionFilter
    ) -> list[QueryCondition]:
        fields = AutoGeneratedFileRevisionSearchableFields.own
        return [
            *self.apply_int_filter(filter.revision_number, fields.revision_number.filter),
            *self.apply_datetime_filter(filter.created_at, fields.created_at.filter),
        ]

    @staticmethod
    def _convert_revision_order(order: AutoGeneratedFileRevisionOrder) -> QueryOrder:
        fields = AutoGeneratedFileRevisionSearchableFields.own
        ascending = order.direction == OrderDirection.ASC
        match order.field:
            case AutoGeneratedFileRevisionOrderField.REVISION_NUMBER:
                return fields.revision_number.order.apply(ascending)
            case AutoGeneratedFileRevisionOrderField.CREATED_AT:
                return fields.created_at.order.apply(ascending)

    @staticmethod
    def _to_revision_node(revision: AutoGeneratedFileRevisionData) -> AutoGeneratedFileRevisionNode:
        return AutoGeneratedFileRevisionNode(
            id=revision.id,
            field_id=revision.id,
            auto_generated_file_id=revision.file_id,
            revision_number=revision.revision_number,
            data=revision.data,
            permission=revision.perm,
            creator_id=revision.creator_id,
            created_at=revision.created_at,
        )

    @staticmethod
    def _convert_order(order: AutoGeneratedFileOrder) -> QueryOrder:
        fields = AutoGeneratedFileSearchableFields.own
        ascending = order.direction == OrderDirection.ASC
        match order.field:
            case AutoGeneratedFileOrderField.PATH:
                return fields.path.order.apply(ascending)
            case AutoGeneratedFileOrderField.CREATED_AT:
                return fields.created_at.order.apply(ascending)
            case AutoGeneratedFileOrderField.UPDATED_AT:
                return fields.updated_at.order.apply(ascending)

    @classmethod
    def _scope_type_conditions(
        cls, scope_type: AutoGeneratedFileScopeTypeFilter | None
    ) -> list[QueryCondition]:
        """Every operation the scope-type filter sets, on the owner's entity type."""
        if scope_type is None:
            return []
        column = AutoGeneratedFileSearchableFields.own.entity_type.filter
        conditions: list[QueryCondition] = []
        if scope_type.equals is not None:
            conditions.append(column.equals(cls._entity_type_spec(scope_type.equals, False)))
        if scope_type.not_equals is not None:
            conditions.append(column.equals(cls._entity_type_spec(scope_type.not_equals, True)))
        if scope_type.in_ is not None:
            conditions.append(column.in_(cls._entity_types_spec(scope_type.in_, False)))
        if scope_type.not_in is not None:
            conditions.append(column.in_(cls._entity_types_spec(scope_type.not_in, True)))
        return conditions

    @classmethod
    def _entity_type_spec(
        cls, scope_type: AutoGeneratedFileScopeType, negated: bool
    ) -> StringMatchSpec:
        return StringMatchSpec(
            value=cls._entity_type(scope_type), case_insensitive=False, negated=negated
        )

    @classmethod
    def _entity_types_spec(
        cls, scope_types: list[AutoGeneratedFileScopeType], negated: bool
    ) -> StringInMatchSpec:
        return StringInMatchSpec(
            values=[cls._entity_type(one) for one in scope_types],
            case_insensitive=False,
            negated=negated,
        )

    @staticmethod
    def _entity_type(scope_type: AutoGeneratedFileScopeType) -> EntityType:
        match scope_type:
            case AutoGeneratedFileScopeType.DOMAIN:
                return DomainEntityType()
            case AutoGeneratedFileScopeType.PROJECT:
                return ProjectEntityType()
            case AutoGeneratedFileScopeType.USER:
                return UserEntityType()

    def _to_node(self, file: AutoGeneratedFileData) -> AutoGeneratedFileNode:
        return AutoGeneratedFileNode(
            id=file.id,
            entity_id=file.id,
            scope_type=self._scope_type(file.entity),
            scope_id=file.entity,
            path=file.path,
            is_default=file.is_default,
            created_at=file.created_at,
            updated_at=file.updated_at,
        )

    @staticmethod
    def _scope_entity(ref: AutoGeneratedFileScopeInput) -> EntityIdentifier:
        match ref.scope_type:
            case AutoGeneratedFileScopeType.DOMAIN:
                return DomainID(ref.scope_id)
            case AutoGeneratedFileScopeType.PROJECT:
                return ProjectID(ref.scope_id)
            case AutoGeneratedFileScopeType.USER:
                return UserID(ref.scope_id)
            case _:
                raise UnreachableError(f"No auto-generated file is owned by a {ref.scope_type}")

    @staticmethod
    def _scope_type(owner: EntityIdentifier) -> AutoGeneratedFileScopeType:
        match owner.entity_type():
            case entity_type if entity_type == DomainEntityType():
                return AutoGeneratedFileScopeType.DOMAIN
            case entity_type if entity_type == ProjectEntityType():
                return AutoGeneratedFileScopeType.PROJECT
            case entity_type if entity_type == UserEntityType():
                return AutoGeneratedFileScopeType.USER
            case _:
                raise UnreachableError(
                    f"No auto-generated file is owned by a {owner.entity_type()}"
                )
